//     for (i = 0; i < k; ++i) y[i] = z[i];
//     y[k] = alpha;
//   }
//
// This implementation keeps the same scalar recurrence but applies two
// optimizations:
//
// 1) Eliminate the temporary vector z[] by doing the y-update in place,
//    using symmetric pairs (i, j = k-1-i). For each k:
//
//        y_i_new = y_i_old + alpha * y_j_old
//        y_j_new = y_j_old + alpha * y_i_old
//
//    for all i < j, and if k is odd, for the middle index m = (k-1)/2:
//
//        y_m_new = y_m_old + alpha * y_m_old.
//
//    This is algebraically identical to the original z-based update, but
//    halves the memory traffic on y and removes the O(N) temporary buffer.
//
// 2) Keep all iteration over data dimensions expressed with Noarr traversers
//    (as required), but avoid creating and traversing the extra z-bag.
//
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(auto r, auto y) {
	using namespace noarr;

	// length of the 1D vectors
	auto n = r | get_length<'i'>();

	// pseudo-structure for the k loop (algorithmic time dimension)
	auto k_structure = noarr::scalar<char>() ^ noarr::vector<'k'>(n);

	num_t alpha;
	num_t beta;
	num_t sum;

	#pragma scop
	// Initial conditions:
	// y[0] = -r[0];
	// beta = 1.0;
	// alpha = -r[0];
	y[noarr::idx<'i'>(0)] = -r[noarr::idx<'i'>(0)];
	beta = SCALAR_VAL(1.0);
	alpha = -r[noarr::idx<'i'>(0)];

	// for (k = 1; k < n; k++)
	//
	// We express the k-loop using a traverser over a synthetic 'k' dimension
	// and restrict it to k in [1, n-1] via slice<'k'>(1, n-1).
	noarr::traverser(k_structure)
		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			auto k_state = k_trav.state();
			auto k = noarr::get_index<'k'>(k_state); // this is the original k in [1, n-1]

			// beta = (1 - alpha * alpha) * beta;
			// uses alpha from the previous k-iteration
			beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

			// sum = 0.0;
			sum = SCALAR_VAL(0.0);

			// sum over i = 0..k-1:
			//   sum += r[k - i - 1] * y[i];
			//
			// Implemented as a Noarr traversal over the prefix y[0..k-1].
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k))
				.for_each([&](auto i_state) {
					auto i = noarr::get_index<'i'>(i_state);

					// Access r in reverse: r[k-1-i]
					auto r_state = noarr::idx<'i'>(k - 1 - i);
					sum += r[r_state] * y[i_state];
				});

			// alpha = - (r[k] + sum) / beta;
			alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

			// In-place symmetric update of y[0..k-1], equivalent to:
			//   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
			//   for (i = 0; i < k; i++) y[i] = z[i];
			//
			// We only iterate i over [0, floor(k/2)) and update the symmetric
			// pair (i, j = k-1-i) once. For odd k, the middle element is
			// handled separately.
			std::size_t pair_count = k / 2; // floor(k/2)

			if (pair_count > 0) {
				noarr::traverser(y)
					.order(noarr::slice<'i'>(0, pair_count))
					.for_each([&](auto i_state) {
						auto i = noarr::get_index<'i'>(i_state);
						std::size_t j = k - 1 - i;

						auto j_state = noarr::idx<'i'>(j);

						// Read old values
						num_t yi = y[i_state];
						num_t yj = y[j_state];

						// Write new values; both depend only on the old pair
						y[i_state] = yi + alpha * yj;
						y[j_state] = yj + alpha * yi;
					});
			}

			// Center element when k is odd: i == j == (k-1)/2
			if (k % 2 == 1) {
				std::size_t m = k / 2; // (k-1)/2 for odd k
				auto m_state = noarr::idx<'i'>(m);
				num_t ym = y[m_state];
				y[m_state] = ym + alpha * ym;
			}

			// y[k] = alpha;
			y[noarr::idx<'i'>(k)] = alpha;
		});
	#pragma endscop
