	// alpha = -r[0];
	y[noarr::idx<'i'>(0)] = -r[noarr::idx<'i'>(0)];
	beta = SCALAR_VAL(1.0);
	alpha = -r[noarr::idx<'i'>(0)];

	// Main Durbin recursion:
	// for (k = 1; k < n; k++)
	noarr::traverser(k_structure)
		// Restrict k to [1, n-1] (start = 1, length = n-1)
		.order(noarr::slice<'k'>(1, n - 1))
		.template for_dims<'k'>([&](auto k_trav) {
			auto k_state = k_trav.state();
			auto k = noarr::get_index<'k'>(k_state); // current k

			// beta = (1 - alpha * alpha) * beta;
			beta = (SCALAR_VAL(1.0) - alpha * alpha) * beta;

			// sum = 0.0;
			sum = SCALAR_VAL(0.0);

			// sum = sum_{i=0}^{k-1} r[k - i - 1] * y[i];
			//
			// We iterate i using a traverser over y (dimension 'i' is contiguous)
			// and compute the matching index into r explicitly as k - 1 - i.
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, k)) // i in [0, k)
				.for_each([&](auto i_state) {
					auto i = noarr::get_index<'i'>(i_state);
					// r index: k - 1 - i
					auto r_index = k - i - 1;

					sum += r.template at<'i'>(r_index) * y[i_state];
				});

			// alpha_new = -(r[k] + sum) / beta;
			num_t alpha_new = -(r.template at<'i'>(k) + sum) / beta;

			// In‑place symmetric update on y[0..k-1] using alpha_new.
			//
			// Original:
			//   for (i = 0; i < k; i++) z[i] = y[i] + alpha * y[k - i - 1];
			//   for (i = 0; i < k; i++) y[i] = z[i];
			//
			// Equivalent in-place formulation:
			//   - For each pair (i, j = k-1-i) with i < j:
			//       y_i' = y_i + alpha_new * y_j
			//       y_j' = y_j + alpha_new * y_i
			//     using the old values y_i, y_j.
			//   - If k is odd, there is a middle index m = k/2 where i == j:
			//       y_m' = y_m + alpha_new * y_m.
			//
			// Each element y[0..k-1] is written exactly once, and all reads
			// use pre-update values. This gives the same result as the
			// z-based formulation but halves memory traffic and removes z.
			auto half = k / 2; // number of distinct pairs (floor(k/2))

			// Process pairs (i, j = k-1-i) with i in [0, half)
			noarr::traverser(y)
				.order(noarr::slice<'i'>(0, half))
				.for_each([&](auto i_state) {
					auto i = noarr::get_index<'i'>(i_state);
					auto j = k - i - 1;

					// Old values from y before this iteration
					num_t y_i_old = y[i_state];
					num_t y_j_old = y.template at<'i'>(j);

					// New values for the pair
					y[i_state]              = y_i_old + alpha_new * y_j_old;
					y.template at<'i'>(j)   = y_j_old + alpha_new * y_i_old;
				});

			// Middle element when k is odd: index m = k/2 satisfies i == j.
			// Only appears once and is updated using its old value.
			if (k % 2 == 1) {
				auto m  = k / 2;
				auto m_state = noarr::idx<'i'>(m);
				num_t y_m_old = y[m_state];
				y[m_state] = y_m_old + alpha_new * y_m_old; // y_m * (1 + alpha_new)
			}

			// y[k] = alpha_new;
			y[noarr::idx<'i'>(k)] = alpha_new;

			// Prepare for next iteration: alpha_{k+1} uses alpha_new
			alpha = alpha_new;
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// input data
	auto set_lengths = noarr::set_length<'i'>(n);

	auto r = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);
	auto y = noarr::bag(noarr::scalar<num_t>() ^ tuning.y_layout ^ set_lengths);

	// initialize data
	init_array(r.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_durbin(r.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (also prevents dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, y.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
